  Map<String, dynamic> toJson() => <String, dynamic>{
        'enabled': enabled,
        'kudosMakers': kudosMakers.toJson(),
        if (limits != null) 'limits': limits!.toJson(),
        'showKudosTotals': showKudosTotals,
        'automaticBadges': automaticBadges,
        'membersMayRequest': membersMayRequest,
        if (credentialValidDays != null)
          'credentialValidDays': credentialValidDays!,
        if (updatedAt != null) 'updatedAt': updatedAt!,
        if (ext != null) 'ext': ext!,
      };
}
